218	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
219	    @Override
220	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
221	        Owner owner = this.clinicService.findOwnerById(ownerId);
222	        if (owner != null) {
223	            Pet pet = owner.getPet(petId);
224	            if (pet != null) {
225	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
226	            }
227	        }
228	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
229	    }
230	
231	    /**
232	     * Applies the intake rules a newly submitted owner must satisfy before it is persisted.
233	     * The address is normalized in place (so a required-field check that follows rejects an
234	     * address blank after normalization), the required fields are checked, the telephone and
235	     * email are normalized in place, and the resulting owner is rejected when its derived
236	     * identity key already belongs to another owner. Each rule
237	     * signals a violation by throwing, which the exception advice renders as the matching 4xx
238	     * response; when the method returns normally {@code ownerFieldsDto} is normalized and ready
239	     * to be mapped and saved.
240	     *
241	     * @param ownerFieldsDto the submitted owner fields, normalized in place
242	     */
243	    private void prepareNewOwner(OwnerFieldsDto ownerFieldsDto, LocalDate registrationDate) {
244	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
245	        validateRequiredFields(ownerFieldsDto);
246	        ownerFieldsDto.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
247	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
248	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
249	        rejectDuplicateIdentity(ownerFieldsDto);
250	        rejectCityAtCapacity(ownerFieldsDto.getCity());
251	        rejectDailyLimitExceeded(registrationDate);
252	    }
253	
254	    /**
255	     * Determines the effective registration date for a newly submitted owner, adjusted so it always
256	     * falls on a business day. The date supplied on the request is used when present, otherwise the
257	     * server's current date is used. When that effective date lands on a Saturday or Sunday it is
258	     * rolled forward to the following Monday; a weekday is left unchanged. This single adjusted date
259	     * is what gets stored as {@code registrationDate} and is what every value derived from it (the
260	     * membership number's year segment, the per-day create limit) is computed against.
261	     *
262	     * A supplied registration date later than the server's current date is rejected with an
263	     * {@link InvalidFieldsException}, which the exception advice renders as a 400 Bad Request.
264	     *
265	     * @param ownerFieldsDto the submitted owner fields, which may carry a registration date
266	     * @return the effective registration date rolled forward to the next business day
267	     */
268	    private LocalDate effectiveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
269	        LocalDate supplied = ownerFieldsDto.getRegistrationDate();
270	        if (supplied != null && supplied.isAfter(LocalDate.now())) {
271	            throw new InvalidFieldsException(List.of("registrationDate"));
272	        }
273	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
274	        return toBusinessDay(effective);
275	    }
276	
277	    /**
278	     * Rolls a date forward to the next business day: a Saturday or Sunday is advanced to the
279	     * following Monday, while a weekday is returned unchanged.
280	     *
281	     * @param date the date to adjust
282	     * @return the same date when it is a weekday, otherwise the next Monday
283	     */
284	    private LocalDate toBusinessDay(LocalDate date) {
285	        java.time.DayOfWeek day = date.getDayOfWeek();
286	        if (day == java.time.DayOfWeek.SATURDAY || day == java.time.DayOfWeek.SUNDAY) {
287	            return date.with(java.time.temporal.TemporalAdjusters.next(java.time.DayOfWeek.MONDAY));
288	        }
289	        return date;
290	    }
291	
292	    /**
293	     * The maximum number of owners that may be created on a single day. Once this many owners
294	     * already carry today's {@code registrationDate}, no further owner may be created today.
295	     */
296	    private static final long DAILY_OWNER_LIMIT = 100L;
297	
298	    /**
299	     * Rejects a new owner when {@link #DAILY_OWNER_LIMIT} or more owners already carry the given
300	     * adjusted business-day {@code registrationDate}. The count is taken against the same adjusted
301	     * date the new owner would be stored with, so owners are capped per business day. When the limit
302	     * has been reached a {@link DailyOwnerLimitExceededException} is thrown, which the exception
303	     * advice renders as a 429 Too Many Requests response.
304	     *
305	     * @param registrationDate the adjusted business-day registration date of the owner being created
306	     */
307	    private void rejectDailyLimitExceeded(LocalDate registrationDate) {
308	        long count = this.clinicService.findAllOwners().stream()
309	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
310	            .count();
311	        if (count >= DAILY_OWNER_LIMIT) {
312	            throw new DailyOwnerLimitExceededException(registrationDate);
313	        }
314	    }
315	
316	    /**
317	     * The number of owners that may carry a single day's {@code registrationDate} before that day
318	     * is flagged as a bulk-signup day. Once more than this many owners share a registration date,
319	     * the create and read responses report {@code bulkSignupWarning} true for that date.
320	     */
321	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
322	
323	    /**
324	     * Reports whether the given business-day {@code registrationDate} is a bulk-signup day, i.e.
325	     * whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry that date. The
326	     * count is taken against the same adjusted date owners are stored with, mirroring the
327	     * per-day create-limit accumulation. A {@code null} date is never a bulk-signup day.
328	     *
329	     * @param registrationDate the adjusted business-day registration date to test, or {@code null}
330	     * @return {@code true} when more than 80 owners share the date, otherwise {@code false}
331	     */
332	    private boolean bulkSignupWarning(LocalDate registrationDate) {
333	        if (registrationDate == null) {
334	            return false;
335	        }
336	        long count = this.clinicService.findAllOwners().stream()
337	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
338	            .count();
339	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
340	    }
341	
342	    /**
343	     * The maximum number of owners a single city may hold. Once a city already contains this
344	     * many owners, no further owner may be created in it.
345	     */
346	    private static final long CITY_OWNER_CAPACITY = 50L;
347	
348	    /**
349	     * Rejects a new owner whose city already contains {@link #CITY_OWNER_CAPACITY} or more owners.
350	     * Cities are compared case-insensitively, consistent with how per-city owners are counted
351	     * elsewhere. When the city is at capacity a {@link CityCapacityExceededException} is thrown,
352	     * which the exception advice renders as a 409 Conflict response.
353	     *
354	     * @param city the city of the owner being created
355	     */
356	    private void rejectCityAtCapacity(String city) {
357	        long count = this.clinicService.findAllOwners().stream()
358	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
359	            .count();
360	        if (count >= CITY_OWNER_CAPACITY) {
361	            throw new CityCapacityExceededException(city);
362	        }
363	    }
364	
365	    /**
366	     * Builds the customer code assigned to a newly created owner. The code is formatted as
367	     * {@code '<REGION>-<HASH8>'}, where {@code REGION} is the owner's canonical region (see
368	     * {@link Owner#getRegion()}), rendered {@code 'UNKNOWN'} when the owner has no known region,
369	     * and {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest over the
370	     * owner's normalized E.164 {@code telephone} concatenated with its {@code lastName}. The code
371	     * carries no sequence number, so two owners sharing a region, telephone and last name resolve to
372	     * the same code. The whole owner is taken so the code is derived from whichever of its fields the
373	     * identity scheme needs.
374	     *
375	     * @param owner the owner being created, whose fields the code is derived from
376	     * @return the formatted customer code
377	     */
378	    private String customerCodeFor(Owner owner) {
379	        String region = owner.getRegion();
380	        String regionCode = region != null ? region : "UNKNOWN";
381	        String hash8 = shaHex(owner.getTelephone() + owner.getLastName(), 8);
382	        return regionCode + "-" + hash8;
383	    }
384	
385	    /**
386	     * Counts the existing owners that share the given {@code firstName} and {@code lastName}
387	     * with the owner being created, compared case-insensitively. The count is taken before the
388	     * new owner is persisted, so it reflects only pre-existing owners and never includes the new
389	     * owner itself. The resulting value is stored on the owner and exposed as {@code namesakeCount}.
390	     *
391	     * @param firstName the first name of the owner being created
392	     * @param lastName the last name of the owner being created
393	     * @return the number of pre-existing owners sharing the same first and last name
394	     */
395	    private int countNamesakes(String firstName, String lastName) {
396	        return (int) this.clinicService.findAllOwners().stream()
397	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
398	                && lastName.equalsIgnoreCase(existing.getLastName()))
399	            .count();
400	    }
401	
402	    /**
403	     * Flags a newly created owner as a possible (soft) duplicate. Reaching this point means the
404	     * owner already cleared {@link #rejectDuplicateIdentity(OwnerFieldsDto)}, so it is not a hard
405	     * duplicate. It is nonetheless a possible duplicate when an existing owner shares its
406	     * {@code lastName} (compared case-insensitively) and its {@code postcode} while carrying a
407	     * different (normalized) {@code telephone}. When such an owner is found, {@code possibleDuplicate}
408	     * is set {@code true} and {@code possibleDuplicateOf} to the matching owner's id; otherwise
409	     * {@code possibleDuplicate} is set {@code false} and no matching id is recorded. An owner without
410	     * a postcode can share no postcode and is never a possible duplicate.
411	     *
412	     * @param owner the owner being created, already carrying its normalized telephone and postcode
413	     */
414	    private void applyPossibleDuplicate(Owner owner) {
415	        owner.setPossibleDuplicate(false);
416	        owner.setPossibleDuplicateOf(null);
417	        findPossibleDuplicate(owner).ifPresent(existing -> {
418	            owner.setPossibleDuplicate(true);
419	            owner.setPossibleDuplicateOf(existing.getId());
420	        });
421	    }
422	
423	    /**
424	     * Finds the existing owner, if any, that makes the given newly created owner a possible (soft)
425	     * duplicate: an owner sharing its {@code lastName} (compared case-insensitively) and its
426	     * {@code postcode} while carrying a different (normalized) {@code telephone}. This is the single
427	     * definition of the soft-duplicate match; {@link #applyPossibleDuplicate(Owner)} only records the
428	     * outcome on the owner. An owner without a postcode can share no postcode and matches nothing, so
429	     * {@link java.util.Optional#empty()} is returned.
430	     *
431	     * @param owner the owner being created, already carrying its normalized telephone and postcode
432	     * @return the matching existing owner, or {@link java.util.Optional#empty()} when none matches
433	     */
434	    private java.util.Optional<Owner> findPossibleDuplicate(Owner owner) {
435	        if (owner.getPostcode() == null) {
436	            return java.util.Optional.empty();
437	        }
438	        return this.clinicService.findAllOwners().stream()
439	            .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName())
440	                && owner.getPostcode().equals(existing.getPostcode())
441	                && !owner.getTelephone().equals(existing.getTelephone()))
442	            .findFirst();
443	    }
444	
445	    /**
446	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city}
447	     * or {@code telephone} is missing or blank. A field that is only whitespace is treated as
448	     * blank. When any field fails, a {@link RequiredFieldsMissingException} is thrown carrying
449	     * the names of every offending field, which the exception advice renders as a 400 response
450	     * with an {@code errors} array.
451	     *
452	     * @param ownerFieldsDto the submitted owner fields
453	     */
454	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
455	        List<String> missing = new ArrayList<>();
456	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
457	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
458	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
459	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
460	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
461	        if (!missing.isEmpty()) {
462	            throw new RequiredFieldsMissingException(missing);
463	        }
464	    }
465	
466	    private void addIfBlank(List<String> missing, String fieldName, String value) {
467	        if (value == null || value.isBlank()) {
468	            missing.add(fieldName);
469	        }
470	    }
471	
472	    /**
473	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets
474	     * are stripped. When a leading {@code '+'} and country code are present they are kept as
475	     * given; otherwise the country code {@code '+61'} is assumed and a single leading
476	     * {@code '0'} is dropped from the national digits. The result must be a {@code '+'}
477	     * followed by 8 to 15 digits. The normalized E.164 value is what gets stored and returned.
478	     * When the value cannot form a valid E.164 number an {@link InvalidFieldsException} is
479	     * thrown, which the exception advice renders as a 400 response naming the {@code telephone}
480	     * field. For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
481	     *
482	     * @param telephone the submitted telephone value
483	     * @return the normalized E.164 telephone
484	     */
485	    private String normalizeTelephone(String telephone) {
486	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
487	        String e164;
488	        if (cleaned.startsWith("+")) {
489	            e164 = "+" + cleaned.substring(1);
490	        } else {
491	            String national = cleaned;
492	            if (national.startsWith("0")) {
493	                national = national.substring(1);
494	            }
495	            e164 = "+61" + national;
496	        }
497	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
498	            throw new InvalidFieldsException(List.of("telephone"));
499	        }
500	        validateNationalNumberLength(e164);
501	        return e164;
502	    }
503	
504	    /**
505	     * The required national-number length (the digits after the country code) for each country
506	     * code we recognize: {@code '+61'} (Australia) requires 9 national digits and {@code '+1'}
507	     * (NANP) requires 10. Keyed by the country-code digits without the leading {@code '+'}.
508	     */
509	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
510	        java.util.Map.of("61", 9, "1", 10);
511	
512	    /**
513	     * Validates the national-number length of an already syntactically valid E.164 telephone
514	     * against its country code. For each recognized country code the digits following the code
515	     * must have exactly the expected length ({@code '+61'} => 9 national digits, {@code '+1'} =>
516	     * 10). When the country code is recognized but the national number is the wrong length an
517	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
518	     * response naming the {@code telephone} field. A country code that is not recognized carries
519	     * no per-country length rule and is left to the general 8-to-15-digit E.164 check.
520	     *
521	     * @param e164 the normalized E.164 telephone (a {@code '+'} followed by digits)
522	     */
523	    private void validateNationalNumberLength(String e164) {
524	        String digits = e164.substring(1);
525	        NATIONAL_NUMBER_LENGTHS.entrySet().stream()
526	            .filter(entry -> digits.startsWith(entry.getKey()))
527	            // longest matching country code wins, so a shorter code cannot shadow a longer one
528	            .max(java.util.Comparator.comparingInt(entry -> entry.getKey().length()))
529	            .ifPresent(entry -> {
530	                int nationalLength = digits.length() - entry.getKey().length();
531	                if (nationalLength != entry.getValue()) {
532	                    throw new InvalidFieldsException(List.of("telephone"));
533	                }
534	            });
535	    }
536	
537	    /**
538	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
539	     * and a domain containing at least one dot, none of the parts holding whitespace or a
540	     * second {@code @}.
541	     */
542	    private static final java.util.regex.Pattern EMAIL_PATTERN =
543	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
544	
545	    /**
546	     * Normalizes an optional owner email. An email is optional, so a {@code null} value is
547	     * accepted and returned unchanged. When present it must be a syntactically valid address;
548	     * the value is stored and returned lower-cased. When present but invalid an
549	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
550	     * response naming the {@code email} field.
551	     *
552	     * @param email the submitted email value, or {@code null} when omitted
553	     * @return the lower-cased email, or {@code null} when none was supplied
554	     */
555	    private String normalizeEmail(String email) {
556	        if (email == null) {
557	            return null;
558	        }
559	        String trimmed = email.trim();
560	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
561	            throw new InvalidFieldsException(List.of("email"));
562	        }
563	        return canonicalEmail(trimmed);
564	    }
565	
566	    /**
567	     * Reduces an email to the canonical form used both to store it and to compare it against
568	     * other owners' emails: surrounding whitespace is trimmed and the value is lower-cased. A
569	     * {@code null} email (none was supplied) canonicalizes to {@code null}. Unlike
570	     * {@link #normalizeEmail(String)} no validation is performed, so this can be applied to a
571	     * value read back off an existing owner without risk of rejecting it. This is the single
572	     * definition of email identity: two emails denote the same address exactly when they
573	     * canonicalize to the same value, so an email stored via {@link #normalizeEmail(String)} and
574	     * an email already on an existing owner can be compared for equality after both pass through
575	     * here. For example {@code "  Jane@Example.COM "} canonicalizes to {@code "jane@example.com"}.
576	     *
577	     * @param email the email to canonicalize, or {@code null} when none was supplied
578	     * @return the trimmed, lower-cased email, or {@code null} when {@code email} is {@code null}
579	     */
580	    private String canonicalEmail(String email) {
581	        if (email == null) {
582	            return null;
583	        }
584	        return email.trim().toLowerCase(java.util.Locale.ROOT);
585	    }
586	
587	    /**
588	     * Validates an optional owner postcode. A postcode is optional, so a {@code null} value is
589	     * accepted and left unchanged. When present it must be exactly 4 digits, and when the owner's
590	     * city has a known region (see {@link Owner#regionForCity(String)}) the postcode must fall
591	     * within that region's inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
592	     * {@code QLD 4000-4099}, see {@link Owner#postcodeRangeForRegion(String)}). A city with no known
593	     * region admits any 4-digit postcode. When present but malformed or out of range for the city's
594	     * region an {@link InvalidFieldsException} is thrown, which the exception advice renders as a
595	     * 400 response naming the {@code postcode} field.
596	     *
597	     * @param postcode the submitted postcode, or {@code null} when omitted
598	     * @param city the owner's city, used to resolve the region whose range the postcode must satisfy
599	     */
600	    private void validatePostcode(String postcode, String city) {
601	        if (postcode == null) {
602	            return;
603	        }
604	        if (!postcode.matches("^[0-9]{4}$")) {
605	            throw new InvalidFieldsException(List.of("postcode"));
606	        }
607	        int[] range = Owner.postcodeRangeForRegion(Owner.regionForCity(city));
608	        if (range != null) {
609	            int value = Integer.parseInt(postcode);
610	            if (value < range[0] || value > range[1]) {
611	                throw new InvalidFieldsException(List.of("postcode"));
612	            }
613	        }
614	    }
615	
616	    /**
617	     * Rejects a new owner whose derived identity key is already used by any existing owner. All
618	     * duplicate detection is consolidated into this single key (see
619	     * {@link Owner#identityKey(String, String, String)}): the normalized E.164 telephone, the
620	     * canonical (trimmed, lower-cased) email and the household identifier the owner would receive,
621	     * joined by {@code '|'}. The submitted telephone and email have already been normalized in
622	     * place, and the household identifier is the value {@link #assignHousehold} would later store
623	     * (see {@link #prospectiveHouseholdId(OwnerFieldsDto)}). An owner is a duplicate only when its
624	     * whole key equals an existing owner's, so a difference in any part — for example two members
625	     * of one household with different telephones — yields distinct keys and is allowed. When a
626	     * match is found a {@link DuplicateIdentityException} is thrown, which the exception advice
627	     * renders as a 409 Conflict response.
628	     *
629	     * @param ownerFieldsDto the submitted owner fields, already normalized in place
630	     */
631	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
632	        String identityKey = Owner.identityKey(ownerFieldsDto.getTelephone(),
633	            canonicalEmail(ownerFieldsDto.getEmail()), prospectiveHouseholdId(ownerFieldsDto));
634	        boolean taken = this.clinicService.findAllOwners().stream()
635	            .anyMatch(existing -> identityKey.equals(Owner.identityKey(existing.getTelephone(),
636	                canonicalEmail(existing.getEmail()), existing.getHouseholdId())));
637	        if (taken) {
638	            throw new DuplicateIdentityException(identityKey);
639	        }
640	    }
641	
642	    /**
643	     * Assigns the shared {@code householdId} for an owner created with {@code sharesHousehold}
644	     * set to {@code true}. The identifier is the one the owner would receive
645	     * ({@link #prospectiveHouseholdId(OwnerFieldsDto)}), derived deterministically from its
646	     * household identity so every owner in the same household resolves to the same stable value.
647	     * The new owner receives that value, and any existing household mates that do not yet carry it
648	     * are updated so the whole household shares one identifier. When the request did not opt in the
649	     * owner is left without a household identifier.
650	     *
651	     * @param owner the newly created owner, mutated in place with its household identifier
652	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
653	     */
654	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
655	        String householdId = prospectiveHouseholdId(ownerFieldsDto);
656	        if (householdId == null) {
657	            return;
658	        }
659	        owner.setHouseholdId(householdId);
660	        linkHouseholdMates(owner, householdId);
661	    }
662	
663	    /**
664	     * Back-fills the shared {@code householdId} onto the given owner's existing household mates (see
665	     * {@link #findHouseholdMates(String, String)}) that do not yet carry it, so a household declared
666	     * by a later member retroactively links the earlier members that were created without opting in.
667	     * A mate already carrying the identifier is left untouched, so only the newly linked mates are
668	     * re-saved.
669	     *
670	     * @param owner the newly created owner whose household the mates are being linked into
671	     * @param householdId the shared household identifier to propagate to the mates
672	     */
673	    private void linkHouseholdMates(Owner owner, String householdId) {
674	        for (Owner mate : findHouseholdMates(owner.getLastName(), owner.getAddress())) {
675	            if (!householdId.equals(mate.getHouseholdId())) {
676	                mate.setHouseholdId(householdId);
677	                this.clinicService.saveOwner(mate);
678	            }
679	        }
680	    }
681	
682	    /**
683	     * Derives the {@code householdId} a newly submitted owner would receive, without needing the
684	     * owner to have been mapped or persisted yet. An owner shares a household only when the request
685	     * opts in via {@code sharesHousehold}; when it does, the identifier is derived deterministically
686	     * from the owner's household identity (its {@code lastName} and {@code address}, see
687	     * {@link #householdIdFor(String, String)}), so it matches the value {@link #assignHousehold} will
688	     * later store and every household mate resolves to the same identifier. When the request did not
689	     * opt in the owner belongs to no shared household and {@code null} is returned.
690	     *
691	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
692	     * @return the household identifier the owner would receive, or {@code null} when it shares none
693	     */
694	    private String prospectiveHouseholdId(OwnerFieldsDto ownerFieldsDto) {
695	        if (!sharesHousehold(ownerFieldsDto)) {
696	            return null;
697	        }
698	        return householdIdFor(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
699	    }
700	
701	    /**
702	     * Reports whether a submitted owner opted into sharing a household, i.e. whether its request
703	     * carried {@code sharesHousehold} set to {@code true}. A {@code null} or {@code false} flag is
704	     * not opting in. This is the single reading of the {@code sharesHousehold} intent, shared by
705	     * every rule that treats a declared household member differently from an independent owner.
706	     *
707	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
708	     * @return {@code true} when the request opted into sharing a household
709	     */
710	    private boolean sharesHousehold(OwnerFieldsDto ownerFieldsDto) {
711	        return Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
712	    }
713	
714	    /**
715	     * Derives the stable {@code householdId} shared by every owner in the household identified by
716	     * the given {@code lastName} and {@code address}. The two fields are normalized exactly as
717	     * household identity is compared elsewhere (case-insensitively, with collapsed whitespace) and
718	     * hashed with SHA-256, so any two owners in the same household — regardless of creation order —
719	     * resolve to the same identifier. The result is formatted as {@code 'HH-<16 hex chars>'}.
720	     *
721	     * @param lastName the household's last name
722	     * @param address the household's address
723	     * @return the deterministic household identifier
724	     */
725	    private String householdIdFor(String lastName, String address) {
726	        return "HH-" + shaHex(householdKey(lastName, address), 16);
727	    }
728	
729	    /**
730	     * Builds the canonical household key that identifies the household a {@code lastName} and
731	     * {@code address} belong to: the two fields normalized exactly as household identity is compared
732	     * elsewhere (case-insensitively, with collapsed whitespace) and joined by {@code '|'}. This is
733	     * the single definition of which owner fields make up a household and how they are normalized;
734	     * {@link #householdIdFor(String, String)} hashes this key into the stored identifier, so any two
735	     * owners in the same household resolve to the same key and therefore the same identifier.
736	     *
737	     * @param lastName the household's last name
738	     * @param address the household's address
739	     * @return the normalized household key
740	     */
741	    private String householdKey(String lastName, String address) {
742	        return collapseWhitespace(lastName).toLowerCase(java.util.Locale.ROOT) + "|"
743	            + normalizeAddress(address).toLowerCase(java.util.Locale.ROOT);
744	    }
745	
746	    /**
747	     * Computes the upper-case hex SHA-256 digest of a string, truncated to its first
748	     * {@code hexChars} characters. The input is hashed as UTF-8 bytes and each digest byte is
749	     * rendered as two upper-case hex digits, so {@code hexChars} characters cover the leading
750	     * {@code ceil(hexChars / 2)} bytes of the digest. This is the single definition of the
751	     * SHA-256 hex derivation shared by every rule that hashes owner fields (for example the
752	     * household identifier). SHA-256 is a required platform algorithm; were it ever unavailable
753	     * an {@link IllegalStateException} is thrown.
754	     *
755	     * @param input the string to hash
756	     * @param hexChars the number of leading upper-case hex characters to return
757	     * @return the first {@code hexChars} upper-case hex characters of the SHA-256 digest
758	     */
759	    private String shaHex(String input, int hexChars) {
760	        try {
761	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
762	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
763	            StringBuilder sb = new StringBuilder();
764	            for (int i = 0; i < digest.length && sb.length() < hexChars; i++) {
765	                sb.append(String.format("%02X", digest[i]));
766	            }
767	            return sb.substring(0, hexChars);
768	        }
769	        catch (java.security.NoSuchAlgorithmException e) {
770	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
771	        }
772	    }
773	
774	    /**
775	     * Counts the owners that belong to the household identified by the given {@code householdId},
776	     * i.e. every owner carrying that exact identifier. The count is taken against the current set
777	     * of owners, so after a create it reflects the household's size including the newly persisted
778	     * owner. An owner without a household (a {@code null} identifier) belongs to no shared
779	     * household and yields {@code 0}.
780	     *
781	     * @param householdId the shared household identifier, or {@code null} when the owner shares no household
782	     * @return the number of owners in the household, or {@code 0} when {@code householdId} is {@code null}
783	     */
784	    private int countHouseholdMembers(String householdId) {
785	        if (householdId == null) {
786	            return 0;
787	        }
788	        return (int) this.clinicService.findAllOwners().stream()
789	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
790	            .count();
791	    }
792	
793	    /**
794	     * Finds every existing owner that shares a household with the given {@code lastName} and
795	     * {@code address}. Both fields are compared case-insensitively and with runs of whitespace
796	     * collapsed to a single space (and surrounding whitespace trimmed), so for example
797	     * {@code "Franklin"} at {@code "110  W. Liberty St."} matches {@code "franklin"} at
798	     * {@code "110 W. Liberty St."}. This is the single definition of household identity shared by
799	     * every rule that reasons about households.
800	     *
801	     * @param lastName the last name to match on
802	     * @param address the address to match on
803	     * @return the owners sharing the household, in encounter order (possibly empty)
804	     */
805	    private List<Owner> findHouseholdMates(String lastName, String address) {
806	        String normalizedLastName = collapseWhitespace(lastName);
807	        String normalizedAddress = normalizeAddress(address);
808	        return this.clinicService.findAllOwners().stream()
809	            .filter(existing -> normalizedLastName.equalsIgnoreCase(collapseWhitespace(existing.getLastName()))
810	                && normalizedAddress.equalsIgnoreCase(normalizeAddress(existing.getAddress())))
811	            .toList();
812	    }
813	
814	    /**
815	     * Collapses a field for household comparison: leading and trailing whitespace is trimmed and
816	     * every internal run of whitespace is reduced to a single space. A {@code null} value collapses
817	     * to the empty string. Case is left untouched so callers can compare case-insensitively.
818	     *
819	     * @param value the value to collapse, or {@code null}
820	     * @return the whitespace-collapsed value, never {@code null}
821	     */
822	    private String collapseWhitespace(String value) {
823	        if (value == null) {
824	            return "";
825	        }
826	        return value.trim().replaceAll("\\s+", " ");
827	    }
828	
829	    /**
830	     * Common street-type abbreviations expanded during address normalization, keyed by their
831	     * upper-cased token.
832	     */
833	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
834	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
835	
836	    /**
837	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
838	     * leading and trailing whitespace is trimmed, every internal run of whitespace is collapsed to
839	     * a single space, the value is upper-cased, and common street-type abbreviations are expanded
840	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value
841	     * normalizes to the empty string, and an address that holds only whitespace normalizes to the
842	     * empty string so the required-field check rejects it. For example {@code "  12  main  st "}
843	     * becomes {@code "12 MAIN STREET"}. This is the single definition of address normalization used
844	     * everywhere an address is stored or compared.
845	     *
846	     * @param address the submitted address value, or {@code null}
847	     * @return the normalized address, never {@code null}
848	     */
849	    private String normalizeAddress(String address) {
850	        if (address == null) {
851	            return "";
852	        }
853	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
854	        if (collapsed.isEmpty()) {
855	            return "";
856	        }
857	        String[] tokens = collapsed.split(" ");
858	        StringBuilder sb = new StringBuilder(collapsed.length());
859	        for (int i = 0; i < tokens.length; i++) {
860	            if (i > 0) {
861	                sb.append(' ');
862	            }
863	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
864	        }
865	        return sb.toString();
866	    }
867	}
