15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
22	    @Mapping(target = "initials", expression = "java(initials(owner))")
23	    @Mapping(target = "locality", expression = "java(locality(owner))")
24	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
25	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
26	    OwnerDto toOwnerDto(Owner owner);
27	
28	    /**
29	     * Derives the owner's age band as the DTO enum, rendering the owner's derived age band (see
30	     * {@link Owner#getAgeBand()}). Returns {@code null} when the owner has no derivable age band
31	     * (no birthDate or no registrationDate), leaving {@code ageBand} absent from the response.
32	     */
33	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
34	        if (owner == null || owner.getAgeBand() == null) {
35	            return null;
36	        }
37	        return OwnerDto.AgeBandEnum.valueOf(owner.getAgeBand());
38	    }
39	
40	    /**
41	     * Derives the owner's preferred contact channel: {@code 'EMAIL'} when an email address
42	     * is present (non-null and non-blank), otherwise {@code 'PHONE'}.
43	     */
44	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
45	        if (owner == null) {
46	            return null;
47	        }
48	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
49	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
50	    }
51	
52	    /**
53	     * Derives the owner's locality from the region its identity carries (see
54	     * {@link #localityRegion(Owner)}). Returns that region string, or {@code 'UNKNOWN'} when the
55	     * owner has no known region.
56	     */
57	    default String locality(Owner owner) {
58	        if (owner == null) {
59	            return null;
60	        }
61	        String region = localityRegion(owner);
62	        return region != null ? region : "UNKNOWN";
63	    }
64	
65	    /**
66	     * Resolves the region an owner's {@link #locality(Owner)} is derived from. This is the
67	     * {@code REGION} segment carried by the owner's {@code customerCode}, whose new
68	     * {@code '<REGION>-<HASH8>'} identity encodes the region ahead of the first {@code '-'}. The
69	     * sentinel {@code 'UNKNOWN'} region (used when the owner has no known region) and a missing
70	     * customer code both resolve to {@code null}. Keeping the region source in its own method leaves
71	     * {@link #locality(Owner)} owning only the {@code null -> 'UNKNOWN'} rendering, so where the
72	     * region itself comes from can change without disturbing that rendering.
73	     *
74	     * @param owner the owner whose locality region is resolved, never {@code null}
75	     * @return the region string, or {@code null} when the owner has no known region
76	     */
77	    default String localityRegion(Owner owner) {
78	        String code = owner.getCustomerCode();
79	        if (code == null) {
80	            return null;
81	        }
82	        int dash = code.indexOf('-');
83	        String region = dash >= 0 ? code.substring(0, dash) : code;
84	        return "UNKNOWN".equals(region) ? null : region;
85	    }
86	
87	    /**
88	     * Formats an owner's stored names as {@code 'LastName, FirstName'}.
89	     */
90	    default String displayName(Owner owner) {
91	        if (owner == null) {
92	            return null;
93	        }
94	        return owner.getLastName() + ", " + owner.getFirstName();
95	    }
96	
97	    /**
98	     * Returns the owner's initials as the upper-cased first letters of firstName and
99	     * lastName, dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
100	     */
101	    default String initials(Owner owner) {
102	        if (owner == null) {
103	            return null;
104	        }
105	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
106	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
107	    }
108	
109	    Owner toOwner(OwnerDto ownerDto);
110	
111	    @Mapping(target = "id", ignore = true)
112	    @Mapping(target = "pets", ignore = true)
113	    Owner toOwner(OwnerFieldsDto ownerDto);
114	
115	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
116	
117	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
118	
119	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
120	        OwnerPageDto ownerPageDto = new OwnerPageDto();
121	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
122	        ownerPageDto.setPage(ownerPage.getNumber());
123	        ownerPageDto.setSize(ownerPage.getSize());
124	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
125	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
126	        return ownerPageDto;
127	    }
128	}
